$string['exportwarningmore'] = 'And {$a} more line(s) whose format is not the one expected.';
$string['exportwarningnovalue'] = '(missing)';
$string['exportwithdrawalnotice'] = 'Withdrawing an attestation after this export has no effect on this archive, nor on any copy of it.';
